using EEMS.SharedKernel.Domain;namespace EEMS.Modules.Operations.Domain;public sealed class ReadinessState:Entity<short>{private ReadinessState(){}private ReadinessState(short id,string code,string name,short rank){if(id<=0||rank<=0)throw new ArgumentOutOfRangeException(nameof(id));Id=id;Code=OperationRules.Text(code,40);Name=OperationRules.Text(name,100);Rank=rank;IsActive=true;}public string Code{get;private set;}=string.Empty;public string Name{get;private set;}=string.Empty;public short Rank{get;private set;}public bool IsActive{get;private set;}public static ReadinessState Create(short id,string code,string name,short rank)=>new(id,code,name,rank);}
